  <div id="lb" style="position:absolute;top:860px;left:0;width:940px;text-align:center;color:var(--acc2);font-size:42px;font-weight:800;opacity:0;letter-spacing:1px;">GOLD STANDARD FRONTEND</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:4;stroke-linecap:round;opacity:0.2">
    <path id="l0" d="M470 260 L470 290" />
    <path id="l1" d="M470 470 L470 500" />
  </svg>
`;

const items = ['c0', 'c1', 'c2', 'st', 'lb'].map(id => root.querySelector('#' + id));
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const mt = Math.min(t, d * 0.55);

  // Cards and Text Animation
  items.forEach((el, i) => {
    const s = spr(mt, i * 0.25, 0.85, 10);
    el.style.opacity = s;
    el.style.transform = `translateY(${lerp(60, 0, s)}px) scale(${lerp(0.9, 1, s)})`;
  });

  // Connecting lines
  lines.forEach((l, i) => {
    const s = spr(mt, 0.4 + i * 0.25, 0.9, 8);
    l.el.style.strokeDashoffset = l.len * (1 - s);
    l.el.style.opacity = s * 0.3;
  });

  // Star scale pulse once on appearance
  const starPop = spr(mt, 0.75, 0.6, 12);
  items[3].style.transform = `translateY(${lerp(60, 0, starPop)}px) scale(${lerp(0.8, 1.1, starPop)})`;
  if (mt > 1.5) {
    const settle = spr(mt - 1.5, 0, 0.9, 5);
    items[3].style.transform = `translateY(0px) scale(${lerp(1.1, 1, settle)})`;
  }
}
